export const BODY: string = "\n<p>آپ کے آلات پر ہر تصویر کسی فارمیٹ میں رہتی ہے، اور فارمیٹ ہمیشہ ایک دوسرے سے نہیں ملتے۔ فون HEIC محفوظ کرتے ہیں، کیمرے JPG محفوظ کرتے ہیں، ڈیزائنر PNG میں کام کرتے ہیں، اور ویب سائٹس WebP دیتی ہیں۔ جب غلط فارمیٹ غلط ایپ سے ملے تو فائل سیدھی کھلنے سے انکار کر دیتی ہے۔</p>\n<p>تصویر کنورٹر اس بے میل کو حل کرتا ہے۔ یہ فائل کو ایک فارمیٹ میں پڑھتا ہے اور دوسرے میں لکھتا ہے، خود تصویر کو برقرار رکھتے ہوئے۔ پکسل ایک جیسے رہتے ہیں، مگر کنٹینر بدل جاتا ہے، اس لیے فائل جہاں آپ کو چاہیے، وہاں کام کرتی ہے۔</p>\n<p>یہ رہنما بتاتا ہے کہ تصویر تبدیلی کیسے کام کرتی ہے، کون سے فارمیٹ چنیں، اور ہر بار صاف نتائج کیسے پائیں۔ اس میں کوالٹی ترتیبات، شفافیت، بیچ تبدیلی، اور وہ غلطیاں شامل ہیں جو سب سے زیادہ وقت ضائع کرتی ہیں۔</p>\n<h2 id=\"what-is-an-image-converter\">تصویر کنورٹر کیا ہے؟</h2>\n<p>تصویر کنورٹر وہ ٹول ہے جو تصویر کا فائل فارمیٹ بدلتا ہے بغیر اسے بدلے جو تصویر دکھاتی ہے۔ آپ اسے JPG دیتے ہیں، اور وہ آپ کو PNG، WebP، یا کوئی بھی دوسرا فارمیٹ واپس دیتا ہے جسے وہ سپورٹ کرتا ہے۔</p>\n<p>تبدیلی دوبارہ لکھتی ہے کہ پکسل کیسے محفوظ ہوتے ہیں۔ JPG رنگ نقصان والی کمپریشن کے ساتھ محفوظ کرتا ہے، جبکہ PNG انہیں بغیر نقصان کے محفوظ کرتا ہے۔ تصویر ایک جیسی لگتی ہے، مگر فائل ایپس اور ویب سائٹس پر مختلف برتاؤ کرتی ہے۔</p>\n<p>لوگ عملی وجوہات سے تصویریں بدلتے ہیں، تفریح کے لیے نہیں۔ فارم شاید صرف JPG قبول کرے، ویب سائٹ WebP مانگے، یا پرنٹ شاپ PNG پر اصرار کرے۔ کنورٹر آپ کے پاس جو ہے اور جو مانگا گیا ہے، اس کے درمیان پل بناتا ہے۔</p>\n<h2 id=\"formats-the-converter-handles\">کنورٹر کون سے فارمیٹ سنبھالتا ہے؟</h2>\n<p>کنورٹر ان پٹ کے طور پر JPG، PNG، WebP، HEIC، SVG، BMP، GIF اور AVIF قبول کرتا ہے۔ یہ فون کی تصویروں، کیمرہ شاٹ، اسکرین شاٹ، لوگو، اور جدید ویب سائٹس سے ڈاؤن لوڈ کو پورا کرتا ہے۔</p>\n<p>آؤٹ پٹ کے لیے آپ JPG، PNG یا WebP چن سکتے ہیں۔ یہ تین تقریباً ہر حقیقی دنیا کی ضرورت پورا کرتے ہیں: تصویروں کے لیے JPG، گرافکس اور شفافیت کے لیے PNG، اور ویب کے لیے WebP۔</p>\n<p>HEIC خاص ذکر کا مستحق ہے کیونکہ آئی فون پہلے سے طے شدہ طور پر اس فارمیٹ میں تصویریں محفوظ کرتے ہیں۔ کئی ونڈوز پروگرام اور اپ لوڈ فارم اب بھی HEIC فائلیں مسترد کرتے ہیں، اس لیے انہیں JPG میں بدلنا یہاں سب سے عام کاموں میں سے ایک ہے۔</p>\n<h2 id=\"how-browser-conversion-works\">براؤزر تبدیلی کیسے کام کرتی ہے؟</h2>\n<p>جب آپ کنورٹر میں فائل ڈالیں تو آپ کا براؤزر اسے بلٹ ان تصویر سپورٹ سے پکسل میں ڈی کوڈ کرتا ہے۔ HEIC فائلوں کے لیے ٹیب کے اندر چھوٹا WebAssembly ڈی کوڈر چلتا ہے، کیونکہ براؤزر HEIC کو مقامی طور پر ڈی کوڈ نہیں کر سکتے۔</p>\n<p>وہ پکسل HTML5 کینوس پر بنائے جاتے ہیں، جو براؤزر کی ڈرائنگ سطح ہے۔ کینوس پھر پکسل کو دوبارہ انکوڈ کرتا ہے، اس بار آپ کے چنے ہوئے فارمیٹ میں، آپ کی چنی ہوئی کوالٹی پر۔</p>\n<p>چونکہ سب کچھ مقامی طور پر ہوتا ہے، تبدیلی کی رفتار آپ کے آلے پر منحصر ہے، آپ کے انٹرنیٹ کنکشن پر نہیں۔ بڑی تصویر جدید فون یا لیپ ٹاپ پر ایک یا دو سیکنڈ میں بدلتی ہے۔</p>\n<h2 id=\"choosing-the-right-output-format\">درست آؤٹ پٹ فارمیٹ چننا</h2>\n<p>JPG تصویروں کے لیے محفوظ ترین انتخاب ہے۔ یہ ہموار گریڈینٹ، جلد لہجے اور مصروف منظر اچھی طرح سنبھالتا ہے، اور دنیا کا ہر آلہ اور ویب سائٹ اسے کھول سکتی ہے۔ جب مطابقت سب سے اہم ہو تو JPG استعمال کریں۔</p>\n<p>PNG درست انتخاب ہے جب آپ کو شفافیت یا بالکل تیز کنارے چاہییں۔ لوگو، آئیکن، متن والے اسکرین شاٹ، اور چپٹے رنگ والے گرافکس، سب PNG فائلوں کے طور پر بہترین لگتے ہیں۔</p>\n<p>WebP ویب کے لیے بہترین انتخاب ہے۔ یہ اسی کوالٹی پر JPG سے چھوٹی فائلیں بناتا ہے، اور PNG کی طرح شفافیت سپورٹ کرتا ہے۔ زیادہ تر جدید براؤزر اور ویب سائٹ بلڈر اب اسے قبول کرتے ہیں۔</p>\n<h2 id=\"quality-settings-explained\">کوالٹی ترتیبات کی وضاحت</h2>\n<p>کوالٹی سلائیڈر کنٹرول کرتا ہے کہ انکوڈر JPG یا WebP فائل لکھتے ہوئے کتنی تفصیل رکھتا ہے۔ زیادہ عدد زیادہ تفصیل رکھتے ہیں اور بڑی فائلیں بناتے ہیں، جبکہ کم عدد فائل سکڑاتے ہیں اور تصویر نرم کرتے ہیں۔</p>\n<p>زیادہ تر تصویروں کے لیے 80 سے 85 فیصد کے قریب ترتیب اچھی کام کرتی ہے۔ اس سطح پر فائل اصل سے کہیں چھوٹی ہے، پھر بھی فرق قریب سے زوم کیے بغیر دیکھنا مشکل ہے۔</p>\n<p>جب PNG چنا جائے تو سلائیڈر غیر فعال ہوتا ہے، اور یہ بگ نہیں ہے۔ PNG بغیر نقصان کا فارمیٹ ہے، اس لیے چننے کے لیے کوئی کوالٹی سطح نہیں۔ ہر پکسل بالکل محفوظ ہوتا ہے، اور فائل سائز جو بھی چاہیے، وہی ہوتا ہے۔</p>\n<h2 id=\"transparency-and-matte-fill\">شفافیت اور میٹ بھرنے والا رنگ</h2>\n<p>JPG شفافیت محفوظ نہیں کر سکتا، اس لیے جب PNG JPG بنے تو دیکھنے والے حصوں کو کچھ بھرنا چاہیے۔ اسے میٹ بھرنے والا رنگ کہتے ہیں، اور آپ بدلنے سے پہلے اسے چن سکتے ہیں۔</p>\n<p>سفید معمول کا انتخاب ہے، کیونکہ زیادہ تر دستاویزات اور ویب صفحے سفید پس منظر پر بیٹھتے ہیں۔ سفید پر بدلا ہوا لوگو سفید صفحے یا ورڈ دستاویز میں قدرتی لگتا ہے۔</p>\n<p>کالا گہرے ڈیزائن کے لیے بہتر کام کرتا ہے، اور برانڈ رنگ مخصوص ویب سائٹ پس منظر سے میل کھا سکتا ہے۔ کنورٹر آپ کو کوئی بھی ہیکس رنگ چننے دیتا ہے، اس لیے آپ صفحے سے بالکل ملا سکتے ہیں۔</p>\n<h2 id=\"converting-batches-and-zip-downloads\">بیچ بدلنا اور ZIP ڈاؤن لوڈ</h2>\n<p>آپ کو ایک وقت میں ایک فائل بدلنے کی ضرورت نہیں۔ ملے جلے فارمیٹ کا پورا فولڈر قطار میں ڈالیں، ایک آؤٹ پٹ فارمیٹ چنیں، اور انہیں ایک ساتھ بدل دیں۔</p>\n<p>ہر فائل الگ بدلتی ہے، اس لیے ایک خراب فائل باقی کو نہیں روک سکتی۔ خراب تصویر غلطی بیج دکھاتی ہے، جبکہ درست فائلیں پھر بھی مکمل ہوتی ہیں اور عام ڈاؤن لوڈ ہوتی ہیں۔</p>\n<p>جب دو یا زیادہ فائلیں مکمل ہوں تو Download All بٹن انہیں ایک ZIP آرکائیو میں باندھ دیتا ہے۔ یہ بیس فائلیں ایک ایک کر کے ڈاؤن لوڈ کرنے سے کہیں آسان ہے۔</p>\n<h2 id=\"heic-photos-from-iphones\">آئی فون سے HEIC تصویریں</h2>\n<p>آئی فون HEIC کے طور پر تصویریں محفوظ کرتے ہیں کیونکہ فارمیٹ JPG کی تقریباً آدھی جگہ میں ایک ہی کوالٹی محفوظ کرتا ہے۔ تجارت مطابقت ہے، کیونکہ ایپل دنیا سے باہر کئی پروگرام HEIC بالکل نہیں کھول سکتے۔</p>\n<p>کنورٹر HEIC فائلوں کو WebAssembly ڈی کوڈر سے ڈی کوڈ کرتا ہے جو آپ کے براؤزر ٹیب کے اندر چلتا ہے۔ یہ HEIC کنٹینر کو مقامی طور پر پڑھتا ہے، تصویر رینڈر کرتا ہے، اور معیاری JPG، PNG یا WebP برآمد کرتا ہے۔</p>\n<p>بدلی ہوئی JPG اکثر اصل HEIC فائلوں سے میگا بائٹ میں بڑی لگتی ہیں۔ یہ عام ہے، کیونکہ HEIC زیادہ مؤثر فارمیٹ ہے۔ JPG بدتر نہیں، وہ صرف کم مؤثر طریقے سے محفوظ ہے۔</p>\n<h2 id=\"svg-and-vector-files\">SVG اور ویکٹر فائلیں</h2>\n<p>SVG فائلیں دوسرے فارمیٹ سے مختلف ہیں کیونکہ وہ شکلیں کوڈ سے بیان کرتی ہیں، پکسل سے نہیں۔ SVG کے طور پر محفوظ لوگو کسی بھی سائز تک اسکیل ہو سکتا ہے بغیر کبھی دھندلا ہوئے۔</p>\n<p>SVG کو PNG یا WebP میں بدلنے سے وہ شکلیں مقررہ سائز پر پکسل میں بدل جاتی ہیں۔ نتیجہ عام ریسٹر تصویر ہے جسے کوئی بھی ایپ کھول سکتی ہے، جو اس وقت مفید ہے جب ویب سائٹ یا فارم SVG قبول نہ کرے۔</p>\n<p>SVG کے اندر لنک شدہ تصویریں سفر میں بچ نہیں پائیں گی، کیونکہ براؤزر تبدیلی کے دوران انہیں لا نہیں سکتا۔ اگر انہیں PNG میں دکھائی دینا ہو تو تصویروں کو SVG کے اندر data URI کے طور پر ایمبیڈ کریں۔</p>\n<h2 id=\"checking-quality-before-saving\">محفوظ کرنے سے پہلے کوالٹی جانچنا</h2>\n<p>ہر بدلی ہوئی کارڈ پر Compare بٹن ہوتا ہے جو اصل اور بدلی ہوئی فائل کا ساتھ ساتھ منظر کھولتا ہے۔ کنارے، متن اور باریک تفصیل جانچنے کے لیے اسپلٹ ہینڈل تصویر پر گھسیٹیں۔</p>\n<p>موازنہ پہلے اور بعد کے فائل سائز بھی دکھاتا ہے۔ وہ عدد آپ کو بتاتا ہے کہ تبدیلی نے واقعی جگہ بچائی یا نہیں، جو ویب تصویروں کا پورا مقصد ہے۔</p>\n<p>ان حصوں میں زوم کریں جو سب سے اہم ہیں۔ چہرے، چھوٹا متن، اور تیز ترچھی لکیریں کمپریشن نقصان پہلے دکھاتی ہیں، جبکہ ہموار آسمان اور دھندلے پس منظر اسے اچھی طرح چھپاتے ہیں۔</p>\n<h2 id=\"privacy-and-local-processing\">رازداری: آپ کی فائلوں کا کیا ہوتا ہے؟</h2>\n<p>تبدیلی آپ کے آلے پر ہوتی ہے، اس لیے آپ کی فائلیں کبھی سرور پر اپ لوڈ نہیں ہوتیں۔ یہ کلاؤڈ خدمت پر براؤزر کنورٹر کا سب سے بڑا رازداری فائدہ ہے۔</p>\n<p>تصویر کو کینوس پر بنانے سے چھپا میٹا ڈیٹا بھی ہٹ جاتا ہے۔ EXIF کیمرہ ڈیٹا، GPS مقام ٹیگ، اور کیمرہ سیریل نمبر تبدیلی میں بچ نہیں پاتے، جو آن لائن فائلیں شیئر کرتے ہوئے آپ کو بچاتا ہے۔</p>\n<p>کوئی اکاؤنٹ نہیں، سرور پر کوئی اپ لوڈ قطار نہیں، اور آپ کی تصویروں کی کوئی کاپی پیچھے نہیں رہتی۔ ٹیب بند کرنے سے سیشن مکمل ختم ہو جاتا ہے۔</p>\n<h2 id=\"common-mistakes-to-avoid\">بچنے والی عام غلطیاں</h2>\n<p>سب سے عام غلطی نقصان والی JPG کو PNG میں بدلنا اور کوالٹی بہتر ہونے کی توقع کرنا ہے۔ وہ نہیں ہو گی۔ PNG خراب پکسل کو مکمل محفوظ کرتا ہے، اس لیے فائل بڑی ہو جاتی ہے جبکہ تصویر پہلے جیسی ہی خراب رہتی ہے۔</p>\n<p>دوسری غلطی میٹ بھرنے والے رنگ کو نظرانداز کرنا ہے۔ کالے بھرنے کے ساتھ JPG میں بدلا شفاف لوگو سفید صفحے پر ٹوٹا لگتا ہے، اور حل بدلنے سے پہلے دس سیکنڈ کا رنگ بدلنا ہے۔</p>\n<p>لوگ یہ بھی بھول جاتے ہیں کہ متحرک GIF یہاں ساکن تصویریں بن جاتی ہیں۔ کینوس صرف پہلا فریم بناتا ہے، اس لیے حرکت ضائع ہو جاتی ہے۔ اگر آپ کو حرکت رکھنی ہو تو GIF کمپریسر استعمال کریں۔</p>\n<h2 id=\"converting-for-different-destinations\">مختلف منزلوں کے لیے بدلنا</h2>\n<p>ہر منزل کا اپنا پسندیدہ فارمیٹ ہے، اور کنورٹر کو آپ کی عادت کی بجائے منزل سے میل کھانا چاہیے۔ ویب سائٹ WebP چاہتی ہے، فارم JPG چاہتا ہے، اور ڈیزائن ٹول PNG چاہتا ہے، اس لیے ایک ہی ماخذ تصویر کو تین مختلف تبدیلیاں چاہییں ہو سکتی ہیں۔</p>\n<p>ویب سائٹس کے لیے WebP ہوشیار ہدف ہے۔ یہ صفحے تیز رکھتا ہے اور شفافیت سپورٹ کرتا ہے، جو لوگو اور تصویروں دونوں کو سوٹ کرتا ہے۔ تصویر کو 80 فیصد کوالٹی پر WebP میں بدلیں اور وہ ورژن اپنی سائٹ پر اپ لوڈ کریں۔</p>\n<p>ای میل کے لیے JPG محفوظ ہدف ہے۔ ای میل کلائنٹ JPG قابل اعتماد دکھاتے ہیں، جبکہ WebP سپورٹ غیر مستقل ہے اور PNG فائلیں اکثر منسلکہ حد کے لیے بہت بڑی ہوتی ہیں۔ 85 فیصد کوالٹی پر JPG عملی انتخاب ہے۔</p>\n<h2 id=\"file-naming-and-organisation\">تبدیلی کے بعد فائل نام دینا اور تنظیم</h2>\n<p>بدلی ہوئی فائلیں واضح ناموں کی مستحق ہیں، کیونکہ IMG_4821.jpg فائلوں کا فولڈر ایک مہینے بعد بیکار ہے۔ اصل نام رکھیں، ایکسٹینشن بدلیں، اور مقصد بیان کرنے والا مختصر ٹیگ شامل کریں، جیسے hero-web.webp یا passport-photo.jpg۔</p>\n<p>بدلی ہوئی فائلیں اصل سے الگ محفوظ کریں۔ converted یا web-ready نام والا فولڈر دو سیٹ الگ رکھتا ہے، اس لیے آپ کبھی غلطی سے ماسٹر کاپی اوور رائٹ نہیں کرتے یا غلط ورژن نہیں بھیجتے۔</p>\n<p>جب بیچ کئی فارمیٹ بنائے تو فی فارمیٹ سب فولڈر استعمال کریں۔ WebP فائلوں کا فولڈر اور JPG فائلوں کا دوسرا فولڈر ایک فولڈر سے آسان ہے جس میں دونوں ہوں، خاص طور پر جب نام ملتے جلتے ہوں۔</p>\n<p>آزمائش کے لیے تیار ہیں؟ <a href=\"/ur/tasveer-convert-karein/\">Image Converter ٹول</a> کھولیں اور فائل ڈالیں۔ قدم بہ قدم ورژن کے لیے <a href=\"/ur/blog/tasveer-format-kaise-convert-karein/\">How to Convert an Image Format</a> پڑھیں، اور کوالٹی سائنس کے لیے <a href=\"/ur/blog/tasveer-format-convert-karne-par-quality-loss/\">Image Format Conversion: Quality Loss and When to Convert</a> دیکھیں۔ اگر آپ کو کئی فائلیں ایک ساتھ بدلنی ہوں تو <a href=\"/ur/bulk-tasveer-convert-karein/\">Bulk Image Converter</a> پورے فولڈر ایک پاس میں سنبھالتا ہے۔</p>\n";

